/**
 * Folds the deployed addresses into packages/fixtures/src/deployment.gen.ts.
 *
 * The rule is that deployment addresses live in deployments/<chainId>.json and
 * nowhere else. The browser bundles cannot read that file, so this copies it
 * rather than letting anyone retype it: a hand-written address in a fixture is
 * an address that can be wrong on screen while the chain says something else.
 *
 * With no deployment the generated file exports `null`, which is what makes
 * the surfaces say `pending` instead of showing an invented address. That is a
 * value, not a placeholder to be tidied away.
 *
 * Two things come out of it. `DEPLOYMENT` is the chain the surfaces default
 * to, and stays whatever was asked for. `DEPLOYMENTS` is every deployment
 * found, keyed by chain id, because Cordon now runs on more than one chain and
 * a surface that reads a name on Sepolia has to reach Sepolia's registry while
 * the rest of the console is still pointed at Arc. Both are generated from the
 * same files, so neither can drift from the other.
 *
 * Usage: node scripts/record-addresses.mjs [chainId]
 */
import { readFileSync, writeFileSync, existsSync, readdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const chainId = Number(process.argv[2] ?? process.env.CORDON_CHAIN_ID ?? 5042002);
const source = resolve(here, `../deployments/${chainId}.json`);
const out = resolve(here, "../../fixtures/src/deployment.gen.ts");

const header =
  `// GENERATED by packages/contracts/scripts/record-addresses.mjs from\n` +
  `// packages/contracts/deployments/<chainId>.json. Do not edit: an address\n` +
  `// typed here is one that can disagree with the chain it names.\n\n` +
  `export type Deployment = {\n` +
  `  chainId: number;\n` +
  `  /** MandateRegistry. */\n` +
  `  registry: string;\n` +
  `  /** TreeVault, the only funding source. */\n` +
  `  vault: string;\n` +
  `  /** ConductRecord, which writes into the ERC-8004 reputation registry. */\n` +
  `  record: string;\n` +
  `  /** The block the contracts were made in. Reading from zero fails on\n` +
  `   *  Arc — the RPC answers \`pruned history unavailable\` — so anything\n` +
  `   *  that queries logs starts here, including the browser. */\n` +
  `  fromBlock: string;\n` +
  `  /** The commit the deploy script ran from. */\n` +
  `  commit: string;\n` +
  `  deployedAt: string;\n` +
  `};\n\n`;

/** Every deployments/<chainId>.json on disk, in chain id order. */
function everyDeployment() {
  const dir = resolve(here, "../deployments");
  const found = [];
  for (const file of readdirSync(dir).sort()) {
    const match = /^(\d+)\.json$/.exec(file);
    if (!match) continue;
    const d = JSON.parse(readFileSync(resolve(dir, file), "utf8"));
    if (!/^0x[0-9a-fA-F]{40}$/.test(d.registry ?? "")) continue;
    found.push(d);
  }
  return found.sort((a, b) => a.chainId - b.chainId);
}

function render(d, indent = "  ") {
  return (
    `{\n` +
    `${indent}  chainId: ${d.chainId},\n` +
    `${indent}  registry: "${d.registry}",\n` +
    `${indent}  vault: "${d.vault}",\n` +
    `${indent}  record: "${d.record}",\n` +
    `${indent}  fromBlock: "${d.fromBlock ?? "0"}",\n` +
    `${indent}  commit: "${d.commit ?? "unknown"}",\n` +
    `${indent}  deployedAt: "${d.deployedAt}",\n` +
    `${indent}}`
  );
}

function everyBlock() {
  const all = everyDeployment();
  if (all.length === 0) return `export const DEPLOYMENTS: Record<number, Deployment> = {};\n`;
  return (
    `\n/** Every chain Cordon is deployed on, keyed by chain id. */\n` +
    `export const DEPLOYMENTS: Record<number, Deployment> = {\n` +
    all.map((d) => `  ${d.chainId}: ${render(d, "  ")},\n`).join("") +
    `};\n`
  );
}

if (!existsSync(source)) {
  writeFileSync(
    out,
    header +
      `/** No deployment on this chain yet, so every surface reads pending. */\n` +
      `export const DEPLOYMENT: Deployment | null = null;\n` +
      everyBlock(),
  );
  console.log(`no deployments/${chainId}.json, so DEPLOYMENT is null`);
  process.exit(0);
}

const d = JSON.parse(readFileSync(source, "utf8"));
for (const field of ["registry", "vault", "record"]) {
  if (!/^0x[0-9a-fA-F]{40}$/.test(d[field] ?? "")) {
    console.error(`deployments/${chainId}.json has no usable ${field}`);
    process.exit(1);
  }
}

writeFileSync(
  out,
  header +
    `export const DEPLOYMENT: Deployment | null = {\n` +
    `  chainId: ${d.chainId},\n` +
    `  registry: "${d.registry}",\n` +
    `  vault: "${d.vault}",\n` +
    `  record: "${d.record}",\n` +
    `  fromBlock: "${d.fromBlock ?? "0"}",\n` +
    `  commit: "${d.commit ?? "unknown"}",\n` +
    `  deployedAt: "${d.deployedAt}",\n` +
    `};\n` +
    everyBlock(),
);
console.log(`wrote ${out} from chain ${d.chainId}`);
